export class Leases {
  constructor() {
    this.next = 0;
    this.current = new Map();
  }
  acquire(key, owner, now, ttl) {
    const prior = this.current.get(key);
    if (prior && prior.until > now) return null;
    const token = { key, owner, generation: ++this.next, until: now + ttl };
    this.current.set(key, token);
    return token;
  }
}

export class Store {
  constructor(leases) {
    this.leases = leases;
    this.values = new Map();
    this.log = [];
  }
  commit(token, value) {
    const current = this.leases.current.get(token.key);
    if (!current || current.owner !== token.owner) return false;
    this.values.set(token.key, value);
    this.log.push({ generation: token.generation, value });
    return true;
  }
}

export function prepare(leases, key, worker, now, value) {
  const token = leases.acquire(key, worker, now, 10);
  return token
    ? { finish: (store) => store.commit(token, value), token }
    : null;
}

